def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "polish_floor": And([
            Not(self.wet_floor_sign_deployed(self.entryway)),
            self.polishing_pad_deployed,
            self.floor_dry(self.tile_row),
            Not(self.floor_polished(self.tile_row))
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
